def test_output_format(run, x):
    out = run(x)
    out = out.strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit()), 'Output must be an integer'
    val = int(out)
    n = int(x.split('\n')[0].split()[0])
    assert 0 <= val <= n, 'Answer must be between 0 and n inclusive'


def test_example1(run, x):
    if x == "2 2\n49 100\n":
        out = run(x).strip()
        assert out == "1", 'Example 1 must output 1'


def test_example2(run, x):
    if x == "4 2\n32 100 33 1\n":
        out = run(x).strip()
        assert out == "2", 'Example 2 must output 2'


def test_example3(run, x):
    if x == "14 5\n48 19 6 9 50 20 3 42 38 43 36 21 44 6\n":
        out = run(x).strip()
        assert out == "5", 'Example 3 must output 5'


