        return
    from math import floor
    m = 0
    time = 0.0
    ptr = 0
    processes = [(-1, 0.0)] * k
    interesting = [False] * n
    while m < n:
        tmin = float('inf')
        for i in range(k):
            pid, start = processes[i]
            if pid == -1:
                continue
            finish = start + a[pid]
            if finish < tmin:
                tmin = finish
        if tmin == float('inf'):
            break
