        time = tmin
        for i in range(k):
            pid, start = processes[i]
            if pid != -1 and abs(start + a[pid] - time) < 1e-9:
                m += 1
                processes[i] = (-1, 0.0)
        for i in range(k):
            if processes[i][0] == -1 and ptr < n:
                processes[i] = (ptr, time)
                ptr += 1
        event_times.append((time, m))
    interesting = [False] * n
    for i in range(k):
        pid, start = processes[i]
        if pid != -1:
            processes[pid] = (pid, start)
