def test_permutation_invariant(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    a = list(map(int, lines[1].split()))
    if n > 8:
        return
    import itertools
    perms = list(itertools.permutations(a))
    first_out = None
    for perm in perms[:5]:
        inp = f'{n} {k}\n' + ' '.join(map(str, perm)) + '\n'
        out = run(inp).strip()
        if first_out is None:
            first_out = out
        else:
            assert out == first_out, f'Output changed on permutation: {perm}'


def test_monotonic_k(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    a = list(map(int, lines[1].split()))
    if k > 1:
        inp_smaller = f'{n} {k-1}\n' + ' '.join(map(str, a)) + '\n'
        out_original = int(run(x).strip())
        out_smaller = int(run(inp_smaller).strip())
        assert out_original <= out_smaller, 'Increasing k cannot increase interesting count'


def test_upper_bound_by_n(run, x):
    out = int(run(x).strip())
    n = int(x.split('\n')[0].split()[0])
    assert out <= n, f'Answer {out} exceeds total submissions n={n}'


def test_lower_bound_zero(run, x):
    out = int(run(x).strip())
    assert out >= 0, 'Answer must be non-negative'


def test_all_fast_solutions(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    a = list(map(int, lines[1].split()))
    if all(ai == 1 for ai in a):
        out = int(run(x).strip())
        if k >= n:
            assert out == 0, 'All a_i=1, k>=n: all finish at t=0, no interesting'
        else:
            pass


def test_single_submission(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    a = list(map(int, lines[1].split()))
    if n == 1:
        out = int(run(x).strip())
        if a[0] == 1:
            assert out == 0, 'Single submission with one test: never interesting'
        else:
            assert 0 <= out <= 1, 'Single submission: answer 0 or 1'

