{
  "rationale": "Each test checks a necessary condition from the spec, focusing on shape, length, lexicographic order, and subset property. Tests 1-3 ensure output format correctness: length k, all letters from s's set, and valid characters. Test 4 uses brute-force verification for small inputs (n*k ≤ 1000) as the strongest check. Tests 5-10 check monotonicity, prefix relationships, and consistency with examples. The brute-force test would be dropped first if runtime becomes a concern, though it's safe here due to small input constraints.",
  "tests": [
    {
      "name": "test_length_k",
      "source": "def test_length_k(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    ans = run(x).strip()
    assert len(ans) == k, f'Output length {len(ans)} != k={k}'"
    },
    {
      "name": "test_subset_of_letters",
      "source": "def test_subset_of_letters(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    ans = run(x).strip()
    letters_s = set(s)
    letters_t = set(ans)
    assert letters_t.issubset(letters_s), f'Letters {letters_t - letters_s} not in {letters_s}'"
    },
    {
      "name": "test_characters_lowercase",
      "source": "def test_characters_lowercase(run, x):
    ans = run(x).strip()
    assert ans.isalpha() and ans.islower(), f'Output contains non-lowercase or non-letter'"
    },
    {
      "name": "test_brute_force_small",
      "source": "def test_brute_force_small(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    if n * k > 1000:
        return  # skip large cases
    letters = sorted(set(s))
    from itertools import product
    candidates = []
    for comb in product(letters, repeat=k):
        t = ''.join(comb)
        if t > s:
            candidates.append(t)
    expected = min(candidates) if candidates else None
    ans = run(x).strip()
    assert ans == expected, f'Brute force mismatch'"
    },
    {
      "name": "test_lexicographically_greater_than_s",
      "source": "def test_lexicographically_greater_than_s(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    ans = run(x).strip()
    assert ans > s, f'Output not lexicographically greater than s'"
    },
    {
      "name": "test_monotonic_with_prefix",
      "source": "def test_monotonic_with_prefix(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    ans = run(x).strip()
    letters = sorted(set(s))
    # If we take prefix of ans of length min(k, n), it must be >= s[:same_len]
    for i in range(min(k, n)):
        if ans[i] != s[i]:
            assert ans[i] > s[i], f'First difference at {i} must be greater'
            break
    else:
        if k > n:
            # ans starts with s, next char must be smallest letter
            assert ans[n] == letters[0], f'When k>n, char after s must be smallest letter'"
    },
    {
      "name": "test_examples_match",
      "source": "def test_examples_match(run, x):
    examples = {
        '3 3\nabc': 'aca',
        '3 2\nabc': 'ac',
        '3 3\nayy': 'yaa',
        '2 3\nba': 'baa'
    }
    if x in examples:
        ans = run(x).strip()
        assert ans == examples[x], f'Example mismatch'"
    },
    {
      "name": "test_no_smaller_valid_string",
      "source": "def test_no_smaller_valid_string(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    if k > 5 or n > 5:
        return  # skip large
    letters = sorted(set(s))
    ans = run(x).strip()
    from itertools import product
    for comb in product(letters, repeat=k):
        t = ''.join(comb)
        if t > s and t < ans:
            assert False, f'Found smaller valid string {t}'"
    },
    {
      "name": "test_when_k_gt_n",
      "source": "def test_when_k_gt_n(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    if k <= n:
        return
    ans = run(x).strip()
    letters = sorted(set(s))
    assert ans.startswith(s), f'When k>n, output must start with s'
    assert all(c == letters[0] for c in ans[n:]), f'Extra chars must be smallest letter'"
    },
    {
      "name": "test_lexicographic_order_property",
      "source": "def test_lexicographic_order_property(run, x):
    nk, s = x.strip().split('\n')
    n, k = map(int, nk.split())
    ans = run(x).strip()
    # Check that for any i, if we change a later char to something smaller,
    # either it becomes <= s or violates subset.
    letters = sorted(set(s))
    for i in range(k):
        for letter in letters:
            if letter >= ans[i]:
                continue
            new = ans[:i] + letter + letters[0] * (k - i - 1)
            if set(new).issubset(set(s)) and new > s:
                # This would be smaller than ans, contradiction
                assert False, f'Changing position {i} to {letter} yields smaller valid string'"
    }
  ]
}

{
  "rationale": "The tests check basic consistency requirements that any correct solution must satisfy. Each test is based directly on statements from the specification (output must be -1 or a positive sum, matrix values must be positive after replacement, strict increasing property must hold, etc.). They do not attempt to recompute the answer. The weakest test is test_negative_one_output, which only checks if -1 is output correctly in some obvious contradiction cases; it would be dropped first if we needed more aggressive checks.",
  "tests": [
    {
      "name": "test_output_format",
      "source": "def test_output_format(run, x):
    out = run(x).strip()
    # Output must be a single integer, possibly negative
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {repr(out)}'
    # If not -1, must be positive (sum of positive numbers after replacement)
    if val != -1:
        assert val > 0, f'Positive sum expected, got {val}'
"
    },
    {
      "name": "test_no_zeros_remain",
      "source": "def test_no_zeros_remain(run, x):
    out = run(x).strip()
    if out == '-1':
        return  # -1 means impossible, no further check
    # Parse input matrix
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Any zero in interior cells means the replacement failed
    for i in range(1, n-1):
        for j in range(1, m-1):
            assert mat[i][j] != 0, f'Zero remains at ({i},{j})'
"
    },
    {
      "name": "test_strict_increasing_rows",
      "source": "def test_strict_increasing_rows(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(m-1):
            assert mat[i][j] < mat[i][j+1], f'Row {i} not strictly increasing at col {j}'
"
    },
    {
      "name": "test_strict_increasing_columns",
      "source": "def test_strict_increasing_columns(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    for j in range(m):
        for i in range(n-1):
            assert mat[i][j] < mat[i+1][j], f'Column {j} not strictly increasing at row {i}'
"
    },
    {
      "name": "test_non_negative_final_values",
