"
    },
    {
      "name": "test_positive_interior_after_replace",
      "source": "def test_positive_interior_after_replace(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # All original interior zeros must become positive
    orig_lines = x.strip().split('\n')
