def test_output_format(run, x):
    out = run(x).strip()
    # Output must be a single integer, possibly negative
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {repr(out)}'
    # If not -1, must be positive (sum of positive numbers after replacement)
    if val != -1:
        assert val > 0, f'Positive sum expected, got {val}'


def test_no_zeros_remain(run, x):
    out = run(x).strip()
    if out == '-1':
        return  # -1 means impossible, no further check
    # Parse input matrix
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # Any zero in interior cells means the replacement failed
    for i in range(1, n-1):
        for j in range(1, m-1):
            assert mat[i][j] != 0, f'Zero remains at ({i},{j})'


def test_strict_increasing_rows(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(m-1):
            assert mat[i][j] < mat[i][j+1], f'Row {i} not strictly increasing at col {j}'


def test_strict_increasing_columns(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    for j in range(m):
        for i in range(n-1):
            assert mat[i][j] < mat[i+1][j], f'Column {j} not strictly increasing at row {i}'


def test_non_negative_final_values(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(m):
            assert mat[i][j] >= 0, f'Negative value at ({i},{j})'


def test_positive_interior_after_replace(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    mat = [list(map(int, lines[i+1].split())) for i in range(n)]
    # All original interior zeros must become positive
    orig_lines = x.strip().split('\n')
    orig_mat = [list(map(int, orig_lines[i+1].split())) for i in range(n)]
    for i in range(1, n-1):
        for j in range(1, m-1):
            if orig_mat[i][j] == 0:
                assert mat[i][j] > 0, f'Zero at ({i},{j}) not replaced with positive'


