def test_output_is_one_of_three_strings(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    allowed = {"Freda's", "Rainbow's", "OMG>.< I don't know!"}
    for line in lines:
        assert line in allowed, f'Invalid output line: {line}'

def test_freda_condition(run, x):
    # Parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        s = lines[i+1]
        if s.endswith('lala.') and not s.startswith('miao.'):
            assert out_lines[i] == "Freda's", f'Should be Freda\'s for: {s}'

def test_rainbow_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        s = lines[i+1]
        if s.startswith('miao.') and not s.endswith('lala.'):
            assert out_lines[i] == "Rainbow's", f'Should be Rainbow\'s for: {s}'

def test_both_conditions_OMG(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        s = lines[i+1]
        if s.startswith('miao.') and s.endswith('lala.'):
            assert out_lines[i] == 'OMG>.< I don\'t know!', f'Should be OMG for: {s}'

def test_neither_condition_OMG(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        s = lines[i+1]
        if not s.startswith('miao.') and not s.endswith('lala.'):
            assert out_lines[i] == 'OMG>.< I don\'t know!', f'Should be OMG for: {s}'

def test_correct_number_of_lines(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    out_lines = out.strip().split('\n')
    assert len(out_lines) == n, f'Expected {n} lines, got {len(out_lines)}'

def test_no_empty_lines_in_output(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    for line in lines:
        assert line != '', 'Empty line in output'

def test_consistent_for_multiple_sentences(run, x):
    # This test ensures each sentence's output is independent.
    # We simply run the condition checks for each sentence; already covered by other tests,
    # but this one ensures that for multi-sentence inputs, each line matches its own condition.
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    for i in range(n):
        s = lines[i+1]
        if s.endswith('lala.') and not s.startswith('miao.'):
            assert out_lines[i] == "Freda's"
        elif s.startswith('miao.') and not s.endswith('lala.'):
            assert out_lines[i] == "Rainbow's"
        else:
            assert out_lines[i] == 'OMG>.< I don\'t know!'

def test_output_no_extra_whitespace(run, x):
    out = run(x)
    lines = out.split('\n')
    for line in lines:
        if line != '':
            assert line == line.strip(), f'Extra whitespace in line: {repr(line)}'

def test_direct_computation_for_small_n(run, x):
    # Directly compute the correct answer from the specification for n <= 10
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # not applicable for given inputs, but guard anyway
    computed = []
    for i in range(n):
        s = lines[i+1]
        if s.endswith('lala.') and not s.startswith('miao.'):
            computed.append("Freda's")
        elif s.startswith('miao.') and not s.endswith('lala.'):
            computed.append("Rainbow's")
        else:
            computed.append('OMG>.< I don\'t know!')
    expected = '\n'.join(computed)
    assert run(x).strip() == expected.strip(), f'Direct computation mismatch'

def test_valid_output_strings(run, x):
    output = run(x)
    lines = output.split('\n')
    # Remove trailing empty line if present
    if lines and lines[-1] == '':
        lines = lines[:-1]
    valid = {"Freda's", "Rainbow's", "OMG>.< I don't know!"}
    for line in lines:
        assert line in valid, f"Invalid output line: '{line}'"

def test_output_line_count_matches_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x)
    output_lines = output.split('\n')
    # Remove trailing empty line if present
    if output_lines and output_lines[-1] == '':
        output_lines = output_lines[:-1]
    assert len(output_lines) == n, f"Expected {n} output lines, got {len(output_lines)}"

def test_freda_ends_with_lala(run, x):
    output = run(x)
    input_lines = x.strip().split('\n')[1:]  # Skip n
    output_lines = output.strip().split('\n')
    for i, (inp, out) in enumerate(zip(input_lines, output_lines)):
        if out == "Freda's":
            assert inp.endswith('lala.'), f"Freda's output but sentence doesn't end with 'lala.': {inp}"

def test_rainbow_starts_with_miao(run, x):
    output = run(x)
    input_lines = x.strip().split('\n')[1:]  # Skip n
    output_lines = output.strip().split('\n')
    for i, (inp, out) in enumerate(zip(input_lines, output_lines)):
        if out == "Rainbow's":
            assert inp.startswith('miao.'), f"Rainbow's output but sentence doesn't start with 'miao.': {inp}"

def test_omg_not_pure_freda_or_rainbow(run, x):
    output = run(x)
    input_lines = x.strip().split('\n')[1:]  # Skip n
    output_lines = output.strip().split('\n')
    for i, (inp, out) in enumerate(zip(input_lines, output_lines)):
        if out == "OMG>.< I don't know!":
            # According to spec, OMG when:
            # 1. Starts with miao. AND ends with lala., OR
            # 2. Satisfies neither condition
            # So we verify it's NOT the case that it's purely Freda or purely Rainbow
            purely_freda = inp.endswith('lala.') and not inp.startswith('miao.')
            purely_rainbow = inp.startswith('miao.') and not inp.endswith('lala.')
            assert not (purely_freda or purely_rainbow), f"OMG output but sentence satisfies pure condition: {inp}"

def test_exact_lala_is_freda(run, x):
    # For single sentence inputs exactly 'lala.'
    lines = x.strip().split('\n')
    if len(lines) == 2 and lines[1] == 'lala.':
        output = run(x).strip()
        assert output == "Freda's", f"Exact 'lala.' should be Freda's, got: {output}"

def test_exact_miao_is_rainbow(run, x):
    # For single sentence inputs exactly 'miao.'
    lines = x.strip().split('\n')
    if len(lines) == 2 and lines[1] == 'miao.':
        output = run(x).strip()
        assert output == "Rainbow's", f"Exact 'miao.' should be Rainbow's, got: {output}"

def test_neither_condition_gives_omg(run, x):
    output = run(x)
    input_lines = x.strip().split('\n')[1:]  # Skip n
    output_lines = output.strip().split('\n')
    for i, (inp, out) in enumerate(zip(input_lines, output_lines)):
        starts_with_miao = inp.startswith('miao.')
        ends_with_lala = inp.endswith('lala.')
        neither = not starts_with_miao and not ends_with_lala
        if neither:
            assert out == "OMG>.< I don't know!", f"Sentence satisfies neither condition but not OMG: {inp}"

def test_multiple_sentences_consistent_format(run, x):
    # For n > 1, each output should be valid
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1:
        output = run(x)
        output_lines = output.strip().split('\n')
        assert len(output_lines) == n
        valid = {"Freda's", "Rainbow's", "OMG>.< I don't know!"}
        for line in output_lines:
            assert line in valid, f"Invalid output in multi-sentence case: {line}"

def test_output_ends_with_newline(run, x):
    output = run(x)
    # Specification examples show output ends with newline
    # All lines should be properly terminated
    lines = output.split('\n')
    # Last line after splitting should be empty if properly newline-terminated
    # But we need to allow case where last line has content (no trailing newline)
    # Actually, looking at examples, output seems to have each result on separate line
    # So we just check it's parseable
    assert output.count('\n') >= int(x.strip().split('\n')[0]) - 1, "Insufficient newlines in output"
    # Check no extra whitespace at end of lines
    for line in output.split('\n'):
        if line:  # Skip empty last line if present
            assert line == line.rstrip(), "Line has trailing whitespace"

