def test_non_empty_output(run, x):
    output = run(x)
    assert output.strip() != '', 'Output must not be empty or only whitespace.'

def test_output_is_printable_ascii(run, x):
    output = run(x)
    for ch in output:
        assert 32 <= ord(ch) <= 126 or ch == '\n', f'Non-printable ASCII character {repr(ch)} in output.'

def test_no_extra_whitespace(run, x):
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == 1, 'Output must have exactly one line.'
    assert output == lines[0] + '\n', 'Output must end with a single newline, no trailing spaces.'

def test_n1_exact_hello_world(run, x):
    if x.startswith('1\n'):
        output = run(x)
        assert output.strip() == 'Hello World', "For N=1 output must be 'Hello World'."

def test_n2_output_is_integer(run, x):
    if x.startswith('2\n'):
        output = run(x)
        stripped = output.strip()
        assert stripped.isdigit() or (stripped[0] == '-' and stripped[1:].isdigit()), 'For N=2 output must be an integer.'

def test_n2_output_range(run, x):
    if x.startswith('2\n'):
        output = run(x)
        val = int(output.strip())
        assert 2 <= val <= 18, 'Sum of A and B (1..9 each) must be between 2 and 18.'

def test_n2_output_matches_sum(run, x):
    if x.startswith('2\n'):
        lines = x.strip().split('\n')
        a = int(lines[1])
        b = int(lines[2])
        expected = a + b
        output = run(x)
        val = int(output.strip())
        assert val == expected, f'Output {val} does not match sum {expected}.'

def test_n2_output_not_hello_world(run, x):
    if x.startswith('2\n'):
        output = run(x)
        stripped = output.strip()
        assert stripped != 'Hello World', "For N=2 output must not be 'Hello World'."

def test_output_no_extra_lines(run, x):
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == 1, 'Output must have exactly one line.'

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), 'Output must end with a newline.'

