    out = run(x)
    if out.strip() == '-1':
        return
    parts = out.strip().split()
    l, r, k = map(int, x.strip().split())
    for part in parts:
        val = int(part)
        assert l <= val <= r, f"value {val} not in [{l},{r}]"


def test_powers_multiple_of_one(run, x):
    # any integer power of k is divisible by 1, trivial but ensures no weird non-integer
    out = run(x)
    if out.strip() == '-1':
        return
    parts = out.strip().split()
    for part in parts:
        val = int(part)
        assert val % 1 == 0


def test_output_sorted_strictly_increasing(run, x):
