def test_all_powers_are_powers_of_k(run, x):
    # This is the key property, but we cannot compute infinitely.
    # For small k and values we can check.
    l, r, k = map(int, x.strip().split())
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    for p in parts:
        val = int(p)
        # brute force check up to some exponent
        # only check if val is small enough
        if val == 1:
            continue  # k^0 always works
        temp = k
        power = 1
        while temp <= val and temp <= 10**9:
            if temp == val:
                break
            temp *= k
            power += 1
        else:
            # if we exceeded, maybe val is huge; skip
            # but if val is small and not power, fail
            if val <= 10**9:
                # try exact check
                # compute k^p
                prod = 1
                for _ in range(100):
                    if prod == val:
                        break
                    if prod > val:
                        assert False, f"{val} is not a power of {k}"
                    prod *= k
                else:
                    assert False, f"{val} is not a power of {k}"


def test_small_inputs_bruteforce(run, x):
    l, r, k = map(int, x.strip().split())
    # only brute force when range is small
    if r > 10**6:
        return
    out = run(x).strip()
    expected_parts = []
    val = 1
    while val <= r:
        if val >= l:
            expected_parts.append(str(val))
        if val > r // k:
            break
        val *= k
    expected = ' '.join(expected_parts) if expected_parts else '-1'
    # allow trailing space in output
    if out.endswith(' '):
        out = out.rstrip()
    assert out == expected, f"brute force mismatch: expected '{expected}', got '{out}'"
